package in.recallradar;
import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@Service @Transactional class TenantService { private final OrganizationRepository orgs; private final MembershipRepository memberships; private final UserRepository users; private final LocationRepository locations; private final SupplierRepository suppliers; private final IngredientRepository ingredients; private final SupplierIngredientRepository supplierIngredients;
 TenantService(OrganizationRepository o,MembershipRepository m,UserRepository u,LocationRepository l,SupplierRepository s,IngredientRepository i,SupplierIngredientRepository si){orgs=o;memberships=m;users=u;locations=l;suppliers=s;ingredients=i;supplierIngredients=si;}
 Organization createWorkspace(AppUser u,String requested){String base=(requested==null||requested.isBlank()?u.fullName+" Workspace":requested).trim();String slug=slug(base);Organization org=orgs.save(new Organization(base,slug));memberships.save(new Membership(u.id,org.id,OrganizationRole.ORG_ADMIN));return org;}
 synchronized void ensureWorkspace(AppUser u){if(memberships.findByUserId(u.id).isEmpty())createWorkspace(u,null);}
 List<OrganizationResponse> organizations(UUID userId){var user=users.findById(userId).orElseThrow();ensureWorkspace(user);return memberships.findByUserId(userId).stream().map(m->{var o=orgs.findById(m.organizationId).orElseThrow();return new OrganizationResponse(o.id.toString(),o.name,o.slug,m.role.name());}).toList();}
 OrganizationResponse createOrganization(UUID userId,OrganizationRequest r){var u=users.findById(userId).orElseThrow();var o=createWorkspace(u,r.name());return new OrganizationResponse(o.id.toString(),o.name,o.slug,OrganizationRole.ORG_ADMIN.name());}
 Membership membership(UUID userId,String requested){var choices=memberships.findByUserId(userId);if(choices.isEmpty()){ensureWorkspace(users.findById(userId).orElseThrow());choices=memberships.findByUserId(userId);}UUID orgId;if(requested==null||requested.isBlank()){if(choices.size()!=1)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Choose an organization using the X-Organization-Id header.");orgId=choices.getFirst().organizationId;}else try{orgId=UUID.fromString(requested);}catch(IllegalArgumentException e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"X-Organization-Id must be a valid UUID.");}return memberships.findByUserIdAndOrganizationId(userId,orgId).orElseThrow(()->new ResponseStatusException(HttpStatus.FORBIDDEN,"You do not belong to this organization."));}
 void requireAdmin(Membership m){if(m.role!=OrganizationRole.ORG_ADMIN)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Organization administrator permission is required.");}
 void requireMasterDataEditor(Membership m){if(!(m.role==OrganizationRole.ORG_ADMIN||m.role==OrganizationRole.FOOD_SAFETY_MANAGER||m.role==OrganizationRole.WAREHOUSE_MANAGER))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Your role cannot change master data.");}
 List<MembershipResponse> members(Membership m){return memberships.findAll().stream().filter(x->x.organizationId.equals(m.organizationId)).map(x->{var u=users.findById(x.userId).orElseThrow();return new MembershipResponse(x.id.toString(),u.id.toString(),u.email,u.fullName,x.role);}).toList();}
 MembershipResponse addMember(Membership current,MembershipRequest r){requireAdmin(current);var u=users.findByEmailIgnoreCase(r.email().trim()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"A user with that email must register before being added."));var m=memberships.findByUserIdAndOrganizationId(u.id,current.organizationId).orElseGet(()->memberships.save(new Membership(u.id,current.organizationId,r.role())));m.role=r.role();return new MembershipResponse(m.id.toString(),u.id.toString(),u.email,u.fullName,m.role);}
 MembershipResponse updateRole(Membership current,UUID id,RoleUpdateRequest r){requireAdmin(current);var m=memberships.findById(id).filter(x->x.organizationId.equals(current.organizationId)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Membership not found."));m.role=r.role();var u=users.findById(m.userId).orElseThrow();return new MembershipResponse(m.id.toString(),u.id.toString(),u.email,u.fullName,m.role);}
 List<LocationResponse> locations(Membership m){return locations.findByOrganizationIdOrderByName(m.organizationId).stream().map(x->new LocationResponse(x.id.toString(),x.name,x.type,x.address,x.active)).toList();}
 LocationResponse createLocation(Membership m,LocationRequest r){requireAdmin(m);var x=locations.save(new Location(m.organizationId,r.name().trim(),r.type(),blank(r.address())));return new LocationResponse(x.id.toString(),x.name,x.type,x.address,x.active);}
 List<IngredientResponse> ingredients(Membership m){return ingredients.findByOrganizationIdOrderByName(m.organizationId).stream().map(x->new IngredientResponse(x.id.toString(),x.name,x.category,x.unit,x.active)).toList();}
 IngredientResponse createIngredient(Membership m,IngredientRequest r){requireMasterDataEditor(m);var x=ingredients.save(new Ingredient(m.organizationId,r.name().trim(),blank(r.category()),r.unit().trim()));return new IngredientResponse(x.id.toString(),x.name,x.category,x.unit,x.active);}
 List<SupplierResponse> suppliers(Membership m){return suppliers.findByOrganizationIdOrderByName(m.organizationId).stream().map(x->supplierResponse(x)).toList();}
 SupplierResponse createSupplier(Membership m,SupplierRequest r){requireMasterDataEditor(m);var x=suppliers.save(new Supplier(m.organizationId,r.name().trim(),blank(r.contactName()),blank(r.email()),blank(r.phone())));return supplierResponse(x);}
 SupplierResponse linkIngredient(Membership m,UUID supplierId,SupplierIngredientRequest r){requireMasterDataEditor(m);var s=suppliers.findByIdAndOrganizationId(supplierId,m.organizationId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Supplier not found."));ingredients.findByIdAndOrganizationId(r.ingredientId(),m.organizationId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Ingredient not found."));supplierIngredients.save(new SupplierIngredient(s.id,r.ingredientId(),blank(r.supplierSku())));return supplierResponse(s);}
 private SupplierResponse supplierResponse(Supplier x){var ids=supplierIngredients.findBySupplierId(x.id).stream().map(si->si.ingredientId.toString()).toList();return new SupplierResponse(x.id.toString(),x.name,x.contactName,x.email,x.phone,x.active,ids);}
 private String slug(String name){String root=name.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]+","-").replaceAll("(^-|-$)","");if(root.isBlank())root="organization";String candidate=root;int n=2;while(orgs.existsBySlug(candidate))candidate=root+"-"+n++;return candidate;}
 private String blank(String s){return s==null||s.isBlank()?null:s.trim();}
}
